INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(22901, 'Matthew 25:12', 'Matthew', 25, 12, '&nbsp;خو هغۀ ورته جواب ورکړو، خبره دا ده چې زۀ تاسو نۀ پېژنم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22902, 'Matthew 25:13', 'Matthew', 25, 13, '&nbsp;ځکه بېدار اوسئ، ولې چې تاسو ته د ورځې او د وخت هيڅ پته نشته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22903, 'Matthew 25:14', 'Matthew', 25, 14, '&nbsp;بيا د آسمان د بادشاهۍ مثال د هغه سړى په شان دے څوک چې په سفر تلو او نوکران يې راوبلل او خپل مال يې ورته وسپارلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22904, 'Matthew 25:15', 'Matthew', 25, 15, '&nbsp;يو له يې د ساتلو دپاره د سرو زرو پينځۀ تيلۍ ورکړې، دوېم له يې دوه او درېم له يې يوه، هر يو له يې د خپل قابليت په مطابق ورکړې، بيا هغه د مُلک نه روان شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22905, 'Matthew 25:16', 'Matthew', 25, 16, '&nbsp;چا ته چې پينځۀ تيلۍ ورکړے شوې وې هغه سمدستى لاړو او سوداګرى يې پرې شروع کړه او پينځۀ تيلۍ يې پرې نورې وګټلې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22906, 'Matthew 25:17', 'Matthew', 25, 17, '&nbsp;او هم هغه شان چې چا ته چې دوه تيلۍ ورکړے شوې وې هغۀ دوه نورې وګټلې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22907, 'Matthew 25:18', 'Matthew', 25, 18, '&nbsp;خو چا له چې يوه تيلۍ ورکړے شوې وه هغه لاړو او په زمکه کښې يې کنده وکنستله او د مالِک هغه پېسې يې په کښې ښخې کړلې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22908, 'Matthew 25:19', 'Matthew', 25, 19, '&nbsp;ډېره موده پس د هغوئ مالِک واپس راغلو او د هغوئ نه يې حساب وغوښتو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22909, 'Matthew 25:20', 'Matthew', 25, 20, '&nbsp;چا له چې يې د سرو زرو پينځۀ تيلۍ ورکړې وې، هغه راغلو او پينځۀ نورې يې ورسره کېښودې او ورته يې ووئيل چې ګوره مالِکه، تا ما له پينځۀ تيلۍ راکړې وې، ما ورسره پينځۀ نورې وګټلې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22910, 'Matthew 25:21', 'Matthew', 25, 21, '&nbsp;مالِک ووئيل، شاباش زما اعتبارى او ايمانداره نوکره، تا په لږ څۀ کښې ځان اعتبارى ثابت کړو، اوس به زۀ تا د ډېر څۀ اختيارمند کړم. راشه او د خپل مالِک په خوشحالۍ کښې شريک شه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22911, 'Matthew 25:22', 'Matthew', 25, 22, '&nbsp;بيا د دوو تيلو هغه کس راغلو او وې وئيل، مالِکه، تا ما ته دوه تيلۍ سپارلې وې، ګوره، ما ورسره دوه نورې وګټلې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22912, 'Matthew 25:23', 'Matthew', 25, 23, '&nbsp;مالِک ورته ووئيل، شاباش، زما اعتبارى او ايمانداره نوکره. تا په لږ څۀ کښې ځان اعتبارى ثابت کړو، اوس به زۀ تا د ډېر څۀ اختيارمند کړم. راشه او د خپل مالِک په خوشحالۍ کښې شريک شه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22913, 'Matthew 25:24', 'Matthew', 25, 24, '&nbsp;بيا هغه څوک راغلو چا ته چې يوه تيلۍ ورکړے شوې وه او وې وئيل، مالِکه، ما ته پته وه چې تۀ يو سخت سړے يې، تۀ يې هلته رېبې چرته چې دې کَرلى نۀ وى، او هلته يې راټولوې چرته چې دې تخم نوستلے نۀ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22914, 'Matthew 25:25', 'Matthew', 25, 25, '&nbsp;نو زۀ ويرېدلم، ځکه لاړم او ستا سرۀ زر مې په زمکه کښې ښخ کړل. ګوره څۀ چې ستا وُو هغه دا دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22915, 'Matthew 25:26', 'Matthew', 25, 26, '&nbsp;مالِک ورته ووئيل، اے بدکاره نوکره، تا ته معلومه وه چې زۀ يې هلته رېبم چرته چې مې کَرلى نۀ وى او هلته يې راټولوم چرته چې مې تخم نوستلے نۀ وى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22916, 'Matthew 25:27', 'Matthew', 25, 27, '&nbsp;نو بيا تا ته پکار وُو چې زما پېسې دې صرافانو له ورکړے وے، نو په واپسۍ به ما هغه مال د ګټې سره حاصل کړے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22917, 'Matthew 25:28', 'Matthew', 25, 28, '&nbsp;هغۀ ووې چې د دۀ نه د سرو زرو هغه تيلۍ واخلئ او د لسو تيلو والا له يې ورکړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22918, 'Matthew 25:29', 'Matthew', 25, 29, '&nbsp;ځکه چې د چا سره چې څۀ وى هغۀ ته به نور هم ورکړے شى تر هغې چې څۀ ترې سېوا هم شى، خو د چا سره چې څۀ نۀ وى هغۀ نه به هغه څۀ هم واخستلے شى چې ورسره وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22919, 'Matthew 25:30', 'Matthew', 25, 30, '&nbsp;نو دا بې‌کاره نوکر تيارې ته وغورزوئ، چرته به چې د ژړا او د غاښونو چيچل وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22920, 'Matthew 25:31', 'Matthew', 25, 31, '&nbsp;هر کله چې اِبن آدم په پوره شان سره راشى او ټولې فرښتې ورسره وى، هغه به بيا په لويئ سره په خپل آسمانى تخت کښېنى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22921, 'Matthew 25:32', 'Matthew', 25, 32, '&nbsp;او ټول قومونه به د هغۀ په وړاندې راجمع کړے شى هغه به خلق په دوو ډلو کښې جدا کړى لکه څنګه چې شپونکے ګډې د چېلو نه جدا کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22922, 'Matthew 25:33', 'Matthew', 25, 33, '&nbsp;او هغه به ګډې ښى لاس ته او چېلۍ ګس لاس ته کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22923, 'Matthew 25:34', 'Matthew', 25, 34, '&nbsp;بيا به بادشاه د ښى لاس خلقو ته ووائى چې راځئ زما د پلار بختورو خلقو، د بادشاهۍ وارثان شئ چې د دُنيا د پېدايښت راسې تاسو له جوړه شوې وه په هغې کښې ورداخل شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22924, 'Matthew 25:35', 'Matthew', 25, 35, '&nbsp;کله چې زۀ اوږے وم تاسو ما له خوراک راکړو، او چې تږے وم د څښلو دپاره مو اوبۀ راکړې، او چې مسافر وم نو تاسو خپل کور ته بوتلم،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22925, 'Matthew 25:36', 'Matthew', 25, 36, '&nbsp;او چې بربنډ وم نو تاسو په جامو پټ کړم، کله چې زۀ ناجوړه وم نو تاسو زما خيال وساتلو او چې په جيل کښې وم نو تاسو زما ملاقات له راغلئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22926, 'Matthew 25:37', 'Matthew', 25, 37, '&nbsp;نو صادقان به جواب ورکړى، مالِکه، دا کله وُو چې مونږ تۀ اوږے وليدلې او خوراک مو درکړو، يا تږے وې او د څښلو دپاره مو اوبۀ درکړې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22927, 'Matthew 25:38', 'Matthew', 25, 38, '&nbsp;او يا مسافر وې او کور ته مو دننه کړې، بربنډ وې او د اغوستلو دپاره مو جامې درکړې؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22928, 'Matthew 25:39', 'Matthew', 25, 39, '&nbsp;مونږ تۀ کله ناروغه يا په قېد کښې ليدلے وې او ملاقات له دې درغلى وُو؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22929, 'Matthew 25:40', 'Matthew', 25, 40, '&nbsp;خو بادشاه به جواب ورکړى، زۀ تاسو ته رښتيا وايم چې تاسو زما په وروڼو کښې د عاجز نه عاجز يو کس سره هم چې څۀ کړى دى نو زما دپاره مو کړى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22930, 'Matthew 25:41', 'Matthew', 25, 41, '&nbsp;بيا به هغه هغوئ ته ووائى، څوک چې به د هغۀ ګس لاس ته وى، اے لعنتيانو، زما د سترګو نه اخوا شئ او هغه تل ابدى اور ته لاړ شئ چې د شېطان او د هغۀ د فرښتو دپاره تيار شوے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22931, 'Matthew 25:42', 'Matthew', 25, 42, '&nbsp;کله چې زۀ اوږے وم تاسو ما له خوراک رانۀ کړو، او چې تږے وم د څښلو دپاره مو اوبۀ رانۀ کړې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22932, 'Matthew 25:43', 'Matthew', 25, 43, '&nbsp;او چې مسافر وم نو کور ته مو دننه نۀ کړم، چې بربنډ وم تاسو د اغوستلو دپاره جامې رانۀ کړې، او کله چې زۀ ناروغه او جيل کښې وم نو تاسو زما ملاقات له رانۀ غلئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22933, 'Matthew 25:44', 'Matthew', 25, 44, '&nbsp;او هغوئ به هم په جواب کښې ووائى، مالِکه، دا کله مونږ تۀ په لوږه، تنده، مسافر، بربنډ، ناروغه يا په جيل کښې ليدلے يې او ستاسو خِدمت مو نۀ دے کړے؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22934, 'Matthew 25:45', 'Matthew', 25, 45, '&nbsp;نو هغۀ ورته جواب ورکړو، زۀ تاسو ته رښتيا وايم، کله چې تاسو د دوئ نه د يو کس سره هم مدد نۀ دے کړے، نو دا تاسو ما سره مدد نۀ دے کړے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22935, 'Matthew 25:46', 'Matthew', 25, 46, '&nbsp;نو بيا به هغوئ ابدى عذاب ته ولېږلے شى، خو صادقان به د تل ژوندون حاصل کړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22936, 'Matthew 26:1', 'Matthew', 26, 1, '&nbsp;کله چې عيسىٰ خپلې خبرې خلاصې کړې نو خپلو مريدانو ته يې وفرمائيل،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22937, 'Matthew 26:2', 'Matthew', 26, 2, '&nbsp;”تاسو خبر يئ چې دوه ورځې پس به د فسح اختر وى، او اِبن آدم به په سولۍ کولو ته وسپارلے شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22938, 'Matthew 26:3', 'Matthew', 26, 3, '&nbsp;بيا مشران اِمامان او د قوم مشران د مشر اِمام کائفس په محل کښې جرګه شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22939, 'Matthew 26:4', 'Matthew', 26, 4, '&nbsp;او هلته هغوئ دا سازش کولو چې عيسىٰ په پټه ونيسو او مړ يې کړُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22940, 'Matthew 26:5', 'Matthew', 26, 5, '&nbsp;خو هغوئ ووئيل چې، ”دا دې د اختر په ورځ نۀ وى، ګنې په خلقو کښې به بلوا جوړه شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22941, 'Matthew 26:6', 'Matthew', 26, 6, '&nbsp;کله چې عيسىٰ د شمعون جذامى په کور کښې په بيتِ‌عنياه کښې وو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22942, 'Matthew 26:7', 'Matthew', 26, 7, '&nbsp;يوه ښځه راغله چې د مرمرو په عطردان کښې ورسره قيمتى خوشبويه عطر وُو، او څنګه چې هغه خوراک ته کښېناستو هغې ورله په سر عطر واچول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22943, 'Matthew 26:8', 'Matthew', 26, 8, '&nbsp;مريدانو چې دا وليدل نو خفه شول. هغوئ ووئيل، ”دا دې ولې ضائع کړل؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22944, 'Matthew 26:9', 'Matthew', 26, 9, '&nbsp;دا خو به په ډېرو پېسو خرڅ شوې وے او پېسې به يې د چا غريبانانو په کار راغلې وے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22945, 'Matthew 26:10', 'Matthew', 26, 10, '&nbsp;عيسىٰ په دې خبر وو او هغوئ ته يې وفرمائيل چې، ”تاسو دا ښځه ولې تنګوئ؟ هغې ما سره ډېر ښۀ کړى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22946, 'Matthew 26:11', 'Matthew', 26, 11, '&nbsp;ځکه چې غريبانان خو به تل تاسو سره وى خو زۀ به درسره تل نۀ يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22947, 'Matthew 26:12', 'Matthew', 26, 12, '&nbsp;هغې چې دا عطر زما په بدن واچول نو زۀ يې د ښخولو دپاره تيار کړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22948, 'Matthew 26:13', 'Matthew', 26, 13, '&nbsp;زۀ تاسو ته رښتيا وايم چې هر چرته چې په دُنيا کښې دا زېرے خوريږى نو څۀ چې هغې وکړل نو دا به هم په دې ياديږى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22949, 'Matthew 26:14', 'Matthew', 26, 14, '&nbsp;نو بيا يهوداه اِسکريوتى چې په هغه دولسو مريدانو کښې يو وو، مشرانو اِمامانو له لاړو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22950, 'Matthew 26:15', 'Matthew', 26, 15, '&nbsp;او ورته يې ووئيل، ”کۀ زۀ په عيسىٰ جاسوسى وکړم نو تاسو به ما له څۀ راکړئ؟“ نو هغوئ ورله دېرش د سپينو زرو سيکې ورکړې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22951, 'Matthew 26:16', 'Matthew', 26, 16, '&nbsp;د هغه وخت نه پس هغه د مخبرۍ د موقعې په تلاش کښې وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22952, 'Matthew 26:17', 'Matthew', 26, 17, '&nbsp;د پتيرې روټۍ د اختر په اوله ورځ عيسىٰ له مريدان راغلل او وې وئيل چې، ”ستا کوم ځائ خوښ دے چې مونږ په کښې تا له د فسح خوراک تيار کړُو؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
